package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-casing and removing spaces and
// punctuation), arranges it into an r x c rectangle (c >= r, c - r <= 1,
// r*c >= len), then reads the rectangle down its columns, left to right.
// The result is emitted as c chunks of r characters joined by spaces;
// chunks shorter than r are padded with trailing spaces.
func Encode(pt string) string {
	var b strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(unicode.ToLower(r))
		}
	}
	n := b.Len()
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := int(math.Ceil(float64(n) / float64(c)))
	s := b.String()

	chunks := make([]string, c)
	for j := 0; j < c; j++ {
		var col strings.Builder
		for i := 0; i < r; i++ {
			idx := i*c + j
			if idx < n {
				col.WriteByte(s[idx])
			} else {
				col.WriteByte(' ')
			}
		}
		chunks[j] = col.String()
	}
	return strings.Join(chunks, " ")
}

